parameters.jsCode:
const resultados = $input.all();

// Solo contamos registros reales de Airtable.
// Always Output Data puede generar un item vacío cuando no hay coincidencias.
const registros = resultados.filter(item => item.json?.id);

const cantidad = registros.length;

// Si existe un único registro, conservamos todos sus campos
// para no romper el resto del workflow.
const registro = cantidad >= 1 ? registros[0].json : {};

return [
  {
    json: {
      ...registro,
      memory_match_count: cantidad,
      duplicate_session_id: cantidad > 1
    }
  }
];

